/// Known operating-system and password manager pasteboard concealment types.
pub const MACOS_CONCEALED_TYPES: &[&str] = &[
    "org.nspasteboard.ConcealedType",
    "org.nspasteboard.AutoGeneratedType",
    "org.nspasteboard.TransientType",
    "com.agilebits.onepassword",
];

pub const WINDOWS_IGNORE_FORMATS: &[&str] = &[
    "Clipboard Viewer Ignore",
    "ExcludeClipboardContentFromMonitor",
];

/// Checks if any of the given pasteboard type identifiers indicate confidential data.
pub fn is_concealed_type(type_identifier: &str) -> bool {
    let lower = type_identifier.to_lowercase();
    MACOS_CONCEALED_TYPES.iter().any(|&c| lower == c.to_lowercase())
        || WINDOWS_IGNORE_FORMATS.iter().any(|&w| lower == w.to_lowercase())
}

/// Checks if an application bundle ID or process name matches the configured exclusion list.
pub fn is_application_excluded(
    source_app_name: Option<&str>,
    source_app_bundle: Option<&str>,
    exclusions: &[String],
) -> bool {
    if exclusions.is_empty() {
        return false;
    }

    let check_match = |candidate: &str| -> bool {
        let candidate_lower = candidate.to_lowercase();
        exclusions.iter().any(|ex| {
            let ex_lower = ex.to_lowercase();
            candidate_lower == ex_lower || candidate_lower.contains(&ex_lower)
        })
    };

    if let Some(name) = source_app_name
        && check_match(name)
    {
        return true;
    }

    if let Some(bundle) = source_app_bundle
        && check_match(bundle)
    {
        return true;
    }

    false
}

/// Simple heuristic detection for high-entropy secrets (private keys, tokens).
/// Returns true if the plain text matches a known secret signature.
pub fn matches_confidential_heuristic(text: &str) -> bool {
    let trimmed = text.trim();

    // 1. Private keys
    if trimmed.starts_with("-----BEGIN")
        && (trimmed.contains("PRIVATE KEY-----") || trimmed.contains("RSA PRIVATE KEY-----"))
    {
        return true;
    }

    // 2. GitHub Personal Access Tokens (ghp_...)
    if (trimmed.starts_with("ghp_") || trimmed.starts_with("gho_")) && trimmed.len() >= 36 {
        return true;
    }

    // 3. AWS Access Key IDs (AKIA...)
    if trimmed.starts_with("AKIA") && trimmed.len() == 20 && trimmed.chars().all(|c| c.is_ascii_alphanumeric()) {
        return true;
    }

    // 4. One-Time Passcodes (OTP) - 6 to 8 standalone digits
    if (trimmed.len() == 6 || trimmed.len() == 8) && trimmed.chars().all(|c| c.is_ascii_digit()) {
        return true;
    }

    false
}

/// Determines whether a plain text snippet represents a Web URL / link.
pub fn is_url(text: &str) -> bool {
    let trimmed = text.trim();
    if trimmed.is_empty() {
        return false;
    }

    // A valid standalone URL should not contain internal whitespace
    if trimmed.chars().any(char::is_whitespace) {
        return false;
    }

    let lower = trimmed.to_lowercase();

    // Standard web and internet protocol schemes
    if lower.starts_with("http://")
        || lower.starts_with("https://")
        || lower.starts_with("ftp://")
        || lower.starts_with("mailto:")
    {
        return true;
    }

    // Common web addresses starting with www. (must have at least one dot in domain)
    if lower.starts_with("www.") && lower.len() > 4 && lower[4..].contains('.') {
        return true;
    }

    false
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_concealed_types_matching() {
        assert!(is_concealed_type("org.nspasteboard.ConcealedType"));
        assert!(is_concealed_type("ORG.NSPASTEBOARD.TRANSIENTTYPE"));
        assert!(is_concealed_type("Clipboard Viewer Ignore"));
        assert!(!is_concealed_type("public.utf8-plain-text"));
    }

    #[test]
    fn test_app_exclusions() {
        let exclusions = vec!["1Password".to_string(), "com.agilebits".to_string()];
        assert!(is_application_excluded(Some("1Password"), None, &exclusions));
        assert!(is_application_excluded(None, Some("com.agilebits.onepassword"), &exclusions));
        assert!(!is_application_excluded(Some("Safari"), Some("com.apple.Safari"), &exclusions));
    }

    #[test]
    fn test_confidential_heuristics() {
        assert!(matches_confidential_heuristic(
            "-----BEGIN RSA PRIVATE KEY-----\nMIIEowIBAAKCAQEA0...\n-----END RSA PRIVATE KEY-----"
        ));
        assert!(matches_confidential_heuristic(
            "ghp_1234567890abcdefghijklmnopqrstuvwxyz"
        ));
        assert!(matches_confidential_heuristic("AKIAIOSFODNN7EXAMPLE"));
        assert!(matches_confidential_heuristic("123456")); // 6-digit OTP
        assert!(matches_confidential_heuristic("87654321")); // 8-digit OTP
        assert!(!matches_confidential_heuristic("Hello World CopyVault"));
        assert!(!matches_confidential_heuristic("12345")); // 5 digits - not OTP
    }

    #[test]
    fn test_is_url_detection() {
        assert!(is_url("https://copyvault.app"));
        assert!(is_url("http://localhost:3000/dashboard"));
        assert!(is_url("https://github.com/rust-lang/rust?tab=readme-ov-file#quick-start"));
        assert!(is_url("www.example.com"));
        assert!(is_url("www.google.com/search?q=tauri"));
        assert!(is_url("mailto:support@copyvault.app"));
        assert!(is_url("ftp://ftp.example.org/resource"));

        // Non-urls
        assert!(!is_url("not a url"));
        assert!(!is_url("https://example.com with extra spaces"));
        assert!(!is_url("fn main() {}"));
        assert!(!is_url(""));
        assert!(!is_url("www.nodots"));
        assert!(!is_url("just a normal text snippet"));
    }
}
